    out.offsets.clear();
    out.images.clear();
    for (int v = 0; v < nv; ++v) {
        VerCtx& V = ctx[v];
        const int R = V.R;
        u128 extra = u128(1 + (R * 4 + 63) / 64) * PAGE_WEIGHT;
        u128 target = V.A[V.id(0, R)].c[budget[v]];
        std::vector<Node> dfs;
        V.buildNode(0, R, budget[v], target, dfs);
        std::vector<Node> bfs = to_bfs(dfs);
        Image img = build_image(V.starts, ci.versions[v].hops, bfs);
        out.nodes.push_back(bfs);
        out.offsets.push_back(img.offsets);
        out.images.push_back(hex_string(img.bytes));
    }
}

